extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	if not check("file_exists", FileAccess.file_exists("res://story/network_story.json"), "Il file res://story/network_story.json deve esistere"):
		return
	var file := FileAccess.open("res://story/network_story.json", FileAccess.READ)
	if not check("file_open", file != null, "Impossibile aprire res://story/network_story.json"):
		return
	var json := JSON.new()
	var err := json.parse(file.get_as_text())
	if not check("json_parse", err == OK, "Il file res://story/network_story.json deve contenere JSON valido"):
		return
	var data: Dictionary = json.data
	check("has_lines", data.has("lines"), "Il JSON deve contenere la chiave 'lines'")
	var lines: Array = data.get("lines", [])

	var choice_sizes: Array[int] = []
	var labels_found: Dictionary = {}
	var targets_used: Array[String] = []
	var jump_targets: Array[String] = []

	for item in lines:
		if item is Dictionary:
			var t: String = item.get("type", "")
			if t == "choice":
				var opts: Array = item.get("options", [])
				choice_sizes.append(opts.size())
				for opt in opts:
					if opt is Dictionary and opt.has("target"):
						targets_used.append(String(opt["target"]))
			elif t == "label":
				var l_id := String(item.get("id", ""))
				if not l_id.is_empty():
					labels_found[l_id] = true
			elif t == "jump":
				var j_target := String(item.get("target", ""))
				if not j_target.is_empty():
					jump_targets.append(j_target)

	check("has_2_options", choice_sizes.has(2), "Deve esserci una scelta con esattamente 2 opzioni")
	check("has_3_options", choice_sizes.has(3), "Deve esserci una scelta con esattamente 3 opzioni")
	check("has_6_options", choice_sizes.has(6), "Deve esserci una scelta con esattamente 6 opzioni")

	var missing_labels := 0
	for target in targets_used:
		if not labels_found.has(target):
			missing_labels += 1
	check("all_targets_valid", missing_labels == 0, "Tutti i target delle scelte devono corrispondere a un id di un comando label (mancanti: %d)" % missing_labels)
	check("has_jumps", jump_targets.size() >= 1, "Devono essere presenti comandi 'jump' per ricongiungere le strade")

